using System.Text.Json;
using System.Text.Json.Nodes;
using OnlyFate.Database;
using Xunit;
namespace OnlyFate.Database.Tests;
public class PoolContractTests
{
 [Theory][InlineData("missingPair")][InlineData("repeatedCharacter")][InlineData("wrongStroke")][InlineData("crossHomophone")][InlineData("candidateFact")]
 public void PublicValidationRebuildsSourceRatherThanTrustingPoolIds(string mutation) {
  var context=PoolTestData.Context();var output=PoolTestData.Selection(context);var n=JsonNode.Parse(context.GetRawText())!;
  switch(mutation){case "missingPair":n["pools"]![0]!["pairIds"]!.AsArray().RemoveAt(0);break;case "repeatedCharacter":n["pools"]![0]!["firstCharacters"]![1]=n["pools"]![0]!["firstCharacters"]![0]!.DeepClone();break;case "wrongStroke":n["pools"]![0]!["lastCharacters"]![0]!["kangxiStrokes"]=99;break;case "crossHomophone":n["pools"]![0]!["lastCharacters"]![0]!["readings"]=n["pools"]![0]!["firstCharacters"]![0]!["readings"]!.DeepClone();break;default:n["candidates"]![0]!["grids"]!["total"]=99;break;}
  Assert.NotEmpty(NamingContract.Validate(output,JsonSerializer.SerializeToElement(n)));
 }
 [Theory][InlineData("oneGroup")][InlineData("threeAlternatives")][InlineData("duplicate")][InlineData("outsidePool")][InlineData("sameDirection")][InlineData("samePool")][InlineData("longLabel")][InlineData("guarantee")]
 public void SelectionRequiresTwoDistinctGroupsAndFiveValidExamples(string mutation){var context=PoolTestData.Context();var n=JsonNode.Parse(PoolTestData.Selection(context).GetRawText())!;
  switch(mutation){case "oneGroup":n["groups"]!.AsArray().RemoveAt(1);break;case "threeAlternatives":n["groups"]![0]!["alternatives"]!.AsArray().RemoveAt(0);break;case "duplicate":n["groups"]![0]!["alternatives"]![0]=n["groups"]![0]!["recommendation"]!.DeepClone();break;case "outsidePool":n["groups"]![0]!["recommendation"]!["candidateId"]=n["groups"]![1]!["recommendation"]!["candidateId"]!.DeepClone();break;case "sameDirection":n["groups"]![1]!["direction"]=n["groups"]![0]!["direction"]!.DeepClone();break;case "samePool":n["groups"]![1]!["poolId"]=n["groups"]![0]!["poolId"]!.DeepClone();break;case "longLabel":n["groups"]![0]!["label"]=new string('字',25);break;default:n["groups"]![0]!["recommendation"]!["reason"]="保證財運亨通";break;}
  Assert.NotEmpty(NamingContract.Validate(JsonSerializer.SerializeToElement(n),context));
 }
 [Fact] public void ModelProjectionContainsEachCharacterOnceAndNoResearchSources(){var full=PoolTestData.Context();var small=NamingContract.ModelContext(full);var chars=small.GetProperty("characters").EnumerateArray().ToArray();Assert.Equal(chars.Length,chars.Select(c=>c.GetProperty("character").GetString()).Distinct().Count());Assert.DoesNotContain("https",small.GetRawText());foreach(var c in small.GetProperty("candidates").EnumerateArray())Assert.Equal(new[]{"id","name","first","last"},c.EnumerateObject().Select(p=>p.Name));Assert.DoesNotContain("sourceNote",small.GetRawText());Assert.DoesNotContain("elementRationale",small.GetRawText());}
 [Fact] public void ExhaustiveGeneratorIncludesEveryTwentyFivePairPoolAndStableIds(){var real=NamingEngine.Generate(PoolCoreTests.Input,["土","金"]).Candidates[0];var first=Enumerable.Range(0,5).Select(i=>real.First with{Character="F"+i,Readings=["f"+i],KangxiStrokes=9}).ToArray();var last=Enumerable.Range(0,5).Select(i=>real.Last with{Character="L"+i,Readings=["l"+i],KangxiStrokes=16}).ToArray();var pairs=first.SelectMany(f=>last.Select(l=>real with{Id=f.Character+l.Character,First=f,Last=l,Name="林"+f.Character+l.Character,Grids=NamingEngine.Calculate(8,9,16)})).ToArray();var pools=NamingPools.Generate(pairs);var full=Assert.Single(pools,p=>p.FirstCharacters.Count==5&&p.LastCharacters.Count==5);Assert.Equal(25,full.PairIds.Count);Assert.Equal(pools.Select(p=>p.PoolId),NamingPools.Generate(pairs.Reverse().ToArray()).Select(p=>p.PoolId));var incomplete=NamingPools.Generate(pairs.Skip(1).ToArray());Assert.DoesNotContain(incomplete,p=>p.FirstCharacters.Count==5&&p.LastCharacters.Count==5);}
 [Fact] public void DifferentFeasibleRestrictionStillProducesTwoCompletePools(){var source=NamingEngine.Generate(PoolCoreTests.Input with{NoAvoidanceCharacters=false,AvoidCharacters="峻",AvoidMatchMode="same_character"},["金","土"]);var pools=NamingPools.Generate(source.Candidates);NamingPools.RequireTwo(pools);Assert.All(pools,p=>Assert.DoesNotContain("峻",NamingPools.Characters(p)));}
 [Fact] public void DifferentPoolsWithMoreThanTwoSharedCharactersAreRejected(){var context=PoolTestData.Context();var pools=context.GetProperty("pools").EnumerateArray().Where(p=>p.GetProperty("firstCharacters")[0].GetProperty("kangxiStrokes").GetInt32()==13&&p.GetProperty("lastCharacters")[0].GetProperty("kangxiStrokes").GetInt32()==10).Take(2).ToArray();Assert.Equal(2,pools.Length);var n=JsonNode.Parse(PoolTestData.Selection(context).GetRawText())!;HashSet<string> used=[];for(int i=0;i<2;i++){n["groups"]![i]!["poolId"]=pools[i].GetProperty("poolId").GetString();var ids=pools[i].GetProperty("pairIds").EnumerateArray().Select(x=>x.GetString()!).Where(id=>!used.Contains(id)).Take(5).ToArray();n["groups"]![i]!["recommendation"]!["candidateId"]=ids[0];for(int j=0;j<4;j++)n["groups"]![i]!["alternatives"]![j]!["candidateId"]=ids[j+1];used.UnionWith(ids);}var errors=NamingContract.Validate(JsonSerializer.SerializeToElement(n),context);Assert.Contains(errors,e=>e.Contains("跨組重複字"));}
}
